var frequencySort = function(nums) {
    const counts = new Map();
    for (const x of nums) {
        counts.set(x, (counts.get(x) || 0) + 1);
    }
    return nums.slice().sort((a, b) => {
        const ca = counts.get(a), cb = counts.get(b);
        if (ca !== cb) return ca - cb;
        return b - a;
    });
};
